// Original implementation inspired by the public Motion example descriptions.
const clamp01=n=>Math.min(1,Math.max(0,n));
const heroScroll=document.querySelector('.hero-scroll'),heroImg=document.querySelector('.hero-image'),heroCopy=document.querySelector('.hero-content');
const scenes=[...document.querySelectorAll('.drawing-sequence')].map(el=>({el,photo:el.querySelector('.drawing-photo'),scan:el.querySelector('.scan-line'),bar:el.querySelector('.drawing-status i')}));
const interlude=document.querySelector('.interlude'),word=interlude.querySelector('.interlude-word'),parallaxImg=interlude.querySelector('img');
let framePending=false;
function updateExperience(){framePending=false;if(motion.matches)return;const vh=innerHeight,heroRect=heroScroll.getBoundingClientRect();if(heroRect.bottom>0&&heroRect.top<vh){const p=clamp01(-heroRect.top/Math.max(1,heroRect.height-vh));heroImg.style.transform=`scale(${1.04+p*.32})`;heroImg.style.filter=`blur(${p*p*9}px)`;heroImg.style.opacity=String(1-p*.68);heroCopy.style.transform=`translateY(${-p*85}px)`;heroCopy.style.opacity=String(1-clamp01(p*1.6));heroCopy.style.filter=`blur(${p*5}px)`}
for(const s of scenes){const r=s.el.getBoundingClientRect();if(r.bottom<0||r.top>vh)continue;const p=clamp01((-r.top/Math.max(1,r.height-vh)-.06)/.88);s.photo.style.clipPath=`inset(0 ${(1-p)*100}% 0 0)`;s.scan.style.left=`${p*100}%`;s.scan.style.opacity=p>0&&p<1?'1':'0';s.bar.style.transform=`scaleX(${p})`}
const r=interlude.getBoundingClientRect();if(r.bottom>0&&r.top<vh){const p=clamp01((vh-r.top)/(vh+r.height));word.style.transform=`translateX(${(p-.5)*24}%) translateY(${(1-p)*70}px)`;parallaxImg.style.transform=`translateY(${-p*16}%)`;}
}
function scheduleExperience(){if(!framePending){framePending=true;requestAnimationFrame(updateExperience)}}
addEventListener('scroll',scheduleExperience,{passive:true});addEventListener('resize',scheduleExperience);motion.addEventListener('change',scheduleExperience);scheduleExperience();
// A bounded image trail; no continuous loop and no dependence on hover for content.
const intro=document.querySelector('.intro'),trail=intro.querySelector('.cursor-trail'),finePointer=matchMedia('(hover: hover) and (pointer: fine)');
const trailAssets=['jardim','quarto','cafe','cozinha','boutique','varanda'];let lastX=0,lastY=0,lastTime=0,trailIndex=0;
intro.addEventListener('pointermove',event=>{if(motion.matches||!finePointer.matches||event.target.closest('a,button'))return;const now=performance.now();if(now-lastTime<150||Math.hypot(event.clientX-lastX,event.clientY-lastY)<75)return;lastTime=now;lastX=event.clientX;lastY=event.clientY;const rect=intro.getBoundingClientRect(),img=document.createElement('img');img.className='trail-photo';img.alt='';img.src=`assets/${trailAssets[trailIndex++%trailAssets.length]}.jpg`;const x=Math.max(0,Math.min(rect.width-165,event.clientX-rect.left-82)),y=Math.max(0,Math.min(rect.height-210,event.clientY-rect.top-105));img.style.left=x+'px';img.style.top=y+'px';trail.append(img);while(trail.children.length>6)trail.firstElementChild.remove();const rot=(trailIndex%2?1:-1)*9;const animation=img.animate([{opacity:0,transform:`translateY(20px) rotate(${rot}deg) scale(.8)`},{opacity:1,transform:`translateY(0) rotate(${rot}deg) scale(1)`,offset:.2},{opacity:1,transform:`translateY(-8px) rotate(${rot}deg) scale(1)`,offset:.55},{opacity:0,transform:`translateY(-40px) rotate(${rot*.5}deg) scale(.96)`}],{duration:1300,easing:'cubic-bezier(.2,.65,.3,1)'});animation.onfinish=()=>img.remove()});
// Scroll-snap coverflow: arrows, keyboard, drag and optional playback.
const gallery=document.querySelector('.showcase'),track=gallery.querySelector('.gallery-track'),slides=[...track.children],counter=gallery.querySelector('.gallery-counter'),play=gallery.querySelector('.gallery-play');let galleryIndex=0,playTimer=null,galleryFrame=false;
function updateGallery(){galleryFrame=false;const bounds=track.getBoundingClientRect(),center=bounds.left+bounds.width/2;let closest=Infinity;slides.forEach((slide,i)=>{const r=slide.getBoundingClientRect(),distance=(r.left+r.width/2-center)/bounds.width;if(Math.abs(distance)<closest){closest=Math.abs(distance);galleryIndex=i}if(!motion.matches){slide.style.transform=`perspective(1200px) rotateY(${Math.max(-18,Math.min(18,-distance*24))}deg) scale(${1-Math.min(.12,Math.abs(distance)*.13)})`;slide.style.opacity=String(1-Math.min(.35,Math.abs(distance)*.3))}});counter.textContent=`${galleryIndex+1} / ${slides.length}`}
function scheduleGallery(){if(!galleryFrame){galleryFrame=true;requestAnimationFrame(updateGallery)}}
function goToSlide(index){const next=(index+slides.length)%slides.length,slide=slides[next];track.scrollTo({left:slide.offsetLeft-track.offsetLeft-(track.clientWidth-slide.clientWidth)/2,behavior:motion.matches?'instant':'smooth'})}
function stopGallery(){clearInterval(playTimer);playTimer=null;play.setAttribute('aria-pressed','false');play.textContent='Reproduzir galeria ▷'}
gallery.querySelector('.gallery-prev').addEventListener('click',()=>{stopGallery();goToSlide(galleryIndex-1)});gallery.querySelector('.gallery-next').addEventListener('click',()=>{stopGallery();goToSlide(galleryIndex+1)});
track.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();stopGallery();goToSlide(galleryIndex+(e.key==='ArrowRight'?1:-1))}});
track.addEventListener('scroll',scheduleGallery,{passive:true});addEventListener('resize',scheduleGallery);
play.addEventListener('click',()=>{if(playTimer){stopGallery();return}play.setAttribute('aria-pressed','true');play.textContent='Pausar galeria Ⅱ';goToSlide(galleryIndex+1);playTimer=setInterval(()=>goToSlide(galleryIndex+1),3800)});
let drag=null;track.addEventListener('pointerdown',e=>{stopGallery();if(e.pointerType==='mouse'){drag={x:e.clientX,scroll:track.scrollLeft};track.setPointerCapture(e.pointerId);track.style.scrollSnapType='none'}});track.addEventListener('pointermove',e=>{if(drag)track.scrollLeft=drag.scroll-(e.clientX-drag.x)});function endDrag(){if(!drag)return;drag=null;track.style.scrollSnapType='';goToSlide(galleryIndex)}track.addEventListener('pointerup',endDrag);track.addEventListener('pointercancel',endDrag);track.addEventListener('lostpointercapture',endDrag);
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopGallery()});new IntersectionObserver(entries=>{if(!entries[0].isIntersecting)stopGallery()}).observe(gallery);motion.addEventListener('change',()=>{stopGallery();scheduleGallery()});scheduleGallery();
